# Model and parameter recovery for the v05 lab comparison: if the data had
# really been generated by model g, would the fitting procedure (a) recover
# g's parameters, and (b) pick g over the other models?
#
# Synthetic data. A generator model is run on all 47 xsl_datasets conditions
# (n_sim = N_SIM_TRUE learners if stochastic, for an accurate "true" accuracy
# p per item); each item's synthetic accuracy is then Binomial(n, p) / n with
# n = that item's real number of participants. This is exactly the noise model
# behind the SSE floor (noise_ceiling.R), so synthetic data are as noisy as
# the real data.
#
#  param  For each model in PARAM_MODELS, N_DRAWS parameter vectors drawn
#         uniformly within the fitting bounds (log-uniform for scale
#         parameters whose bounds span 100x or more and exceed 1), rejecting draws whose mean predicted accuracy is
#         below .1 or above .95; each synthetic dataset is fit by its own
#         generator.
#  model  For each generator in REC_MODELS, N_REPS synthetic datasets at its
#         v05 group-fit parameters, each fit by every model in REC_MODELS.
#         The winner is the lowest objective, with stochastic fitters
#         re-evaluated at n_sim = 200 at their best parameters (DEoptim's own
#         optimum is biased low for stochastic models, as in Table 1).
#
# Fitting uses the paper's objective (n_subj-weighted SSE, xsl_run()$sse) and
# bounds (fits/v05/specs.R), with a reduced DEoptim budget so that hundreds of
# fits are affordable: NP = max(20, 10 * #params), itermax = 60
# (deterministic) or 25 (stochastic, n_sim = 50); Bayesian_decay gets the
# paper's NP = 100, itermax = 100, and narrower draws (see DRAW_BOUNDS). Each fit runs serially;
# jobs run in parallel across N_CORES. Every job is saved as it finishes
# (recovery/jobs/), so the script is resumable: re-run it to continue.
#
# Usage (from xsl-bakeoff/):
#   R_LIBS=fits/v05/Rlib N_CORES=6 Rscript fits/v05/extras/recovery.R param|model|summarize
#   QUICK=1 ...  tiny budget, 2 generators / 2 draws, output in recovery/quick/
#
# The model phase needs the v05 group fits for every model in REC_MODELS
# (fits/v05/adults/group_fits.Rdata); the param phase doesn't.

source(here::here("fits/v05/extras/common.R"))
suppressMessages(library(parallel))

args  <- commandArgs(trailingOnly = TRUE)
phase <- if (length(args)) args[1] else "summarize"
stopifnot(phase %in% c("param", "model", "summarize", "plan"))
QUICK   <- identical(Sys.getenv("QUICK"), "1")
N_CORES <- as.integer(Sys.getenv("N_CORES", "6"))
OUT <- file.path(EXTRAS_DIR, "recovery", if (QUICK) "quick" else "")
dir.create(file.path(OUT, "jobs"), recursive = TRUE, showWarnings = FALSE)
dir.create(file.path(OUT, "synth"), showWarnings = FALSE)

# One representative per mechanism (as in the appendix's disagreement index),
# plus the sampling FU model, the paper's top stochastic model.
REC_MODELS <- c("baseline", "fazly", "kachergis", "Bayesian_decay", "tilles",
                "trueswell2012", "softmax_rl", "minerva2", "kachergis_sampling")
PARAM_MODELS <- setdiff(REC_MODELS, "baseline")
N_REPS  <- if (QUICK) 1 else as.integer(Sys.getenv("N_REPS", "5"))
N_DRAWS <- if (QUICK) 2 else as.integer(Sys.getenv("N_DRAWS", "20"))
N_SIM_TRUE <- if (QUICK) 5 else 500
N_SIM_FIT  <- if (QUICK) 5 else 50
N_SIM_EVAL <- if (QUICK) 5 else 200
if (QUICK) { REC_MODELS <- c("baseline", "fazly", "trueswell2012"); PARAM_MODELS <- c("fazly", "trueswell2012") }
# PARAM_ONLY=tilles restricts the param phase to the named models, e.g. to
# redo one model's draws under fits/v05/tilles/Rlib without touching the rest
if (nzchar(Sys.getenv("PARAM_ONLY"))) {
  only <- strsplit(Sys.getenv("PARAM_ONLY"), ",")[[1]]
  stopifnot(all(only %in% PARAM_MODELS))
  PARAM_MODELS <- only
}

## ---- synthetic data ------------------------------------------------------------
# scale parameters spanning >= 100x are drawn (and scored) on a log scale;
# probabilities and rates bounded by 1 stay linear
is_logscale <- function(s) s$lower > 0 & s$upper / s$lower >= 100 & s$upper > 1

true_perf <- function(m, par, seed) {
  set.seed(seed)
  map(run_model(m, par, n_sim = N_SIM_TRUE)$fits, \(f) as.vector(f$perf))
}
synth_data <- function(perf, seed) {
  set.seed(seed)
  map2(xsl_datasets, perf, function(d, p) {
    n <- rowSums(d$response_matrix)
    d$accuracy <- rbinom(length(p), n, pmin(pmax(p, 0), 1)) / n
    d
  })
}
# Bayesian_decay: its three parameters trade off, and a linear-space DEoptim
# over its fitting bounds (1e-5..10) can't find small values: on synthetic
# data generated at (.18, .39, .23), even the paper's full budget converged to
# a clearly worse optimum, while near its v05 group fit (~1, 1.4, 1.2) it
# recovered the parameters (checked 2026-10-15). So its true parameters are
# drawn (log-uniformly) from the reachable region below, and it is fitted
# with the paper's group-fit budget rather than the reduced one.
DRAW_BOUNDS <- list(Bayesian_decay = list(lower = c(.5, .5, .5), upper = c(10, 10, 10)))
FULL_BUDGET <- "Bayesian_decay"

draw_par <- function(m, seed) {
  s <- specs_v04[[m]]
  logscale <- is_logscale(s)  # from the fitting bounds, as in the summaries
  if (!is.null(DRAW_BOUNDS[[m]])) s[c("lower", "upper")] <- DRAW_BOUNDS[[m]]
  for (try in 1:50) {
    # each try gets its own stream: true_perf() below reseeds with seed + try,
    # which for a deterministic model left the next try's runif() on draw
    # (i + try)'s first-try stream, so rejected draws repeated their
    # neighbours' accepted ones (2026-10-15). Try 1 is unchanged.
    set.seed(if (try == 1) seed else 100 * seed + try)
    u <- runif(length(s$lower))
    par <- ifelse(logscale, exp(log(s$lower) + u * (log(s$upper) - log(s$lower))),
                  s$lower + u * (s$upper - s$lower))
    # a parameter vector the model can't run (e.g. tilles' NaN choice
    # probabilities) is rejected like an out-of-range one, not fatal
    acc <- tryCatch(mean(unlist(true_perf(m, par, seed + try))), error = \(e) NA_real_)
    if (!is.na(acc) && acc > .1 && acc < .95) return(list(par = unname(par), tries = try, mean_acc = acc))
  }
  stop("no usable parameter draw for ", m)
}
# synthetic dataset for (type, generator, i): cached so every fitter sees the same data
get_synth <- function(type, gen, i, group_pars) {
  f <- file.path(OUT, "synth", sprintf("%s__%s__%02d.rds", type, gen, i))
  if (file.exists(f)) return(readRDS(f))
  seed <- 1e5 * match(type, c("param", "model")) + 1e3 * match(gen, REC_MODELS) + i
  truth <- if (type == "param") draw_par(gen, seed) else list(par = group_pars[[gen]])
  perf <- true_perf(gen, truth$par, seed)
  out <- c(truth, list(type = type, gen = gen, i = i,
                       accuracy = map(synth_data(perf, seed + 7), "accuracy"), true_perf = perf))
  saveRDS(out, f)
  out
}
with_accuracy <- function(acc) map2(xsl_datasets, acc, \(d, a) { d$accuracy <- a; d })

## ---- one fit -----------------------------------------------------------------------
fit_job <- function(job, group_pars) {
  f <- file.path(OUT, "jobs", paste0(job$id, ".rds"))
  if (file.exists(f)) return(invisible(readRDS(f)))
  syn <- get_synth(job$type, job$gen, job$i, group_pars)
  data <- with_accuracy(syn$accuracy)
  spec <- specs_v04[[job$fitter]]
  t0 <- Sys.time()
  set.seed(42 + job$i)
  if (length(spec$lower) == 0) {
    best <- numeric(0)
    obj <- xsl_run(spec$constructor(best), data)$sse
    train <- obj
  } else {
    model <- spec$constructor(spec$lower)
    ctrl  <- if (spec$stochastic) xslControl(n_sim = N_SIM_FIT) else xslControl()
    objective <- function(p) {
      v <- tryCatch(xsl_run(update_params(model, p), data, control = ctrl)$sse, error = \(e) NA_real_)
      if (is.na(v)) Inf else v
    }
    full <- job$fitter %in% FULL_BUDGET
    de <- DEoptim::DEoptim(objective, spec$lower, spec$upper, control = DEoptim::DEoptim.control(
      NP = if (QUICK) 6 else if (full) 100 else max(20, 10 * length(spec$lower)),
      itermax = if (QUICK) 2 else if (full) 100 else if (spec$stochastic) 25 else 60,
      reltol = .001, trace = FALSE))
    best <- unname(de$optim$bestmem); train <- de$optim$bestval
    obj <- if (spec$stochastic) {
      xsl_run(update_params(model, best), data, control = xslControl(n_sim = N_SIM_EVAL))$sse
    } else train
  }
  out <- c(job, list(true_par = syn$par, par = best, train_obj = train, obj = obj,
                     mins = as.numeric(difftime(Sys.time(), t0, units = "mins"))))
  saveRDS(out, f)
  out
}

make_jobs <- function(type) {
  grid <- if (type == "param") {
    expand.grid(gen = PARAM_MODELS, i = seq_len(N_DRAWS), stringsAsFactors = FALSE) |> mutate(fitter = gen)
  } else {
    expand.grid(gen = REC_MODELS, i = seq_len(N_REPS), fitter = REC_MODELS, stringsAsFactors = FALSE)
  }
  grid |>
    mutate(type = type, id = sprintf("%s__%s__%02d__%s", type, gen, i, fitter),
           stochastic = map_lgl(fitter, \(m) specs_v04[[m]]$stochastic)) |>
    # deterministic fitters first, so partial results are useful early
    arrange(stochastic, i, gen)
}

run_phase <- function(type) {
  group_pars <- load_group_pars()
  # only model recovery generates at the group-fit parameters
  missing <- setdiff(REC_MODELS, names(group_pars))
  if (type == "model" && length(missing)) stop("v05 group fits missing for: ", paste(missing, collapse = ", "))
  jobs <- make_jobs(type)
  todo <- filter(jobs, !file.exists(file.path(OUT, "jobs", paste0(id, ".rds"))))
  stamp(type, " recovery: ", nrow(todo), " of ", nrow(jobs), " fits to do, ", N_CORES, " cores",
        if (QUICK) " (QUICK)" else "")
  # make the synthetic datasets first (serially per dataset, in parallel across
  # them), so parallel fits never race to create the same one
  syn <- distinct(todo, type, gen, i)
  invisible(mclapply(seq_len(nrow(syn)), \(r) get_synth(syn$type[r], syn$gen[r], syn$i[r], group_pars),
                     mc.cores = N_CORES))
  res <- mclapply(split(todo, seq_len(nrow(todo))), function(j) {
    out <- tryCatch(fit_job(as.list(j), group_pars), error = \(e) e)
    if (inherits(out, "error")) stamp("FAILED ", j$id, ": ", conditionMessage(out))
    else stamp("done ", j$id, sprintf(" (%.1f min, obj %.4f)", out$mins, out$obj))
    out
  }, mc.cores = N_CORES, mc.preschedule = FALSE)
  n_fail <- sum(map_lgl(res, \(r) inherits(r, "error")))
  stamp(type, " recovery phase finished; ", n_fail, " failures")
}

## ---- summaries --------------------------------------------------------------------------
summarize_recovery <- function() {
  jobs <- map(list.files(file.path(OUT, "jobs"), "\\.rds$", full.names = TRUE), readRDS)
  if (!length(jobs)) stop("no finished recovery jobs in ", OUT)
  md <- c("# Model and parameter recovery (v05)", "",
          paste0("Generated ", format(Sys.time()), " by `fits/v05/extras/recovery.R`", if (QUICK) " (QUICK smoke test)" else "", "."), "")
  out <- list()

  pj <- keep(jobs, \(j) j$type == "param")
  if (length(pj)) {
    pr <- map(pj, \(j) {
      s <- specs_v04[[j$gen]]
      logscale <- is_logscale(s)
      # position within the bounds on the parameter's own scale: a linear
      # tolerance would call anything below .002 "at the bound" for PA's
      # lambda, whose bounds are [1e-10, 2]
      pos <- ifelse(logscale, (log(j$par) - log(s$lower)) / (log(s$upper) - log(s$lower)),
                    (j$par - s$lower) / (s$upper - s$lower))
      tibble(model = j$gen, draw = j$i, param = paste0("p", seq_along(j$par)), logscale = logscale,
             true = j$true_par, fit = j$par, at_bound = pos < 1e-3 | pos > 1 - 1e-3)
    }) |> list_rbind()
    # (scale with if(), not ifelse(): inside summarise() a length-1 logscale
    # made ifelse() return only the first draw)
    on_scale <- function(x, lg) if (lg) log(x) else x
    pr_sum <- pr |> group_by(model, param) |>
      summarise(n = n(), n_distinct_true = n_distinct(true), lg = first(logscale),
                r = suppressWarnings(cor(on_scale(true, lg), on_scale(fit, lg))),
                median_abs_err = median(abs(on_scale(fit, lg) - on_scale(true, lg))),
                at_bound = mean(at_bound), .groups = "drop") |>
      rename(logscale = lg)
    out$param <- list(draws = pr, summary = pr_sum)
    md <- c(md, "## Parameter recovery", "",
            "r = correlation of true and recovered values across draws (log scale where marked); error on the same scale.", "",
            knitr::kable(pr_sum |> mutate(r = sprintf("%.2f", r), median_abs_err = signif(median_abs_err, 3),
                                          at_bound = sprintf("%.0f%%", 100 * at_bound)), format = "pipe"), "")
  }

  mj <- keep(jobs, \(j) j$type == "model")
  if (length(mj)) {
    mr <- map(mj, \(j) tibble(gen = j$gen, rep = j$i, fitter = j$fitter, obj = j$obj)) |> list_rbind()
    complete <- mr |> group_by(gen, rep) |> filter(n() == length(REC_MODELS)) |> ungroup()
    wins <- complete |> group_by(gen, rep) |> slice_min(obj, n = 1, with_ties = FALSE) |> ungroup()
    confusion <- wins |> count(gen, fitter) |> group_by(gen) |> mutate(p = n / sum(n)) |> ungroup()
    inversion <- wins |> count(fitter, gen) |> group_by(fitter) |> mutate(p = n / sum(n)) |> ungroup()
    margin <- complete |> group_by(gen, rep) |>
      summarise(true_obj = obj[fitter == gen], best_other = min(obj[fitter != gen]),
                best_other_model = fitter[fitter != gen][which.min(obj[fitter != gen])], .groups = "drop")
    out$model <- list(fits = mr, wins = wins, confusion = confusion, inversion = inversion, margin = margin)
    wide <- \(x, rows, cols) x |> select(all_of(c(rows, cols)), p) |>
      mutate(p = sprintf("%.2f", p)) |> tidyr::pivot_wider(names_from = all_of(cols), values_from = p, values_fill = "0")
    md <- c(md, "## Model recovery", "",
            paste0(n_distinct(paste(complete$gen, complete$rep)), " complete synthetic datasets (generator x rep). ",
                   "Confusion: P(winning fitter | generator), rows = generator."), "",
            knitr::kable(wide(confusion, "gen", "fitter"), format = "pipe"), "",
            "Inversion: P(generator | winning fitter), rows = winning fitter.", "",
            knitr::kable(wide(inversion, "fitter", "gen"), format = "pipe"), "",
            "Margin: the generator's own objective minus the best other model's (negative = generator wins).", "",
            knitr::kable(margin |> group_by(gen) |>
                           summarise(mean_margin = signif(mean(true_obj - best_other), 3),
                                     closest_rival = names(which.max(table(best_other_model))), .groups = "drop"),
                         format = "pipe"))
  }
  saveRDS(out, file.path(OUT, "recovery.rds"))
  writeLines(md, file.path(OUT, "recovery.md"))
  cat(md, sep = "\n")
}

if (phase == "plan") {
  for (t in c("param", "model")) { j <- make_jobs(t); cat(t, ":", nrow(j), "fits (", sum(j$stochastic), "stochastic )\n") }
} else if (phase == "summarize") {
  summarize_recovery()
} else {
  run_phase(phase)
  summarize_recovery()
}
